function registrationClassViewGroups(registration:any){
 const entries=(registration?.classes??[]).filter((entry:any)=>entry.class?.name||entry.name).slice().sort((a:any,b:any)=>{
  const numberA=Number(a.number?.number??registration.participantNumber??registration.number??0);
  const numberB=Number(b.number?.number??registration.participantNumber??registration.number??0);
  if(numberA!==numberB)return numberA-numberB;
  const directionA=a.class?.direction??{},directionB=b.class?.direction??{};
  const directionOrder=Number(directionA.sortOrder??0)-Number(directionB.sortOrder??0);
  if(directionOrder)return directionOrder;
  const nameA=String(a.class?.name??a.name??''),nameB=String(b.class?.name??b.name??'');
  const bassA=/bass\s*[-_]?\s*race/i.test(String(directionA.name??'')+' '+nameA);
  const bassB=/bass\s*[-_]?\s*race/i.test(String(directionB.name??'')+' '+nameB);
  if(bassA&&bassB){
   const num=(value:string)=>Number(value.match(/\d+(?:[.,]\d+)?/)?.[0]?.replace(',','.'))||Number.MAX_SAFE_INTEGER;
   return num(nameA)-num(nameB)||nameA.localeCompare(nameB,'ru',{numeric:true});
  }
  const classOrder=Number(a.class?.sortOrder??0)-Number(b.class?.sortOrder??0);
  return classOrder||nameA.localeCompare(nameB,'ru',{numeric:true});
 });
 const byNumber=new Map<number,Map<string,any[]>>();
 for(const entry of entries){
  const number=Number(entry.number?.number??registration.participantNumber??registration.number??0);
  const direction=String(entry.class?.direction?.name??'Без направления');
  if(!byNumber.has(number))byNumber.set(number,new Map());
  const byDirection=byNumber.get(number)!;
  if(!byDirection.has(direction))byDirection.set(direction,[]);
  byDirection.get(direction)!.push(entry);
 }
 return [...byNumber.entries()].sort((a,b)=>a[0]-b[0]).map(([number,byDirection])=>({
  number,
  directions:[...byDirection.entries()].map(([name,items])=>({name,items})).sort((a,b)=>{
   const aOrder=Number(a.items[0]?.class?.direction?.sortOrder??0),bOrder=Number(b.items[0]?.class?.direction?.sortOrder??0);
   return aOrder-bOrder||a.name.localeCompare(b.name,'ru');
  })
 }));
}
function RegistrationClassesView({registration,compact=false}:{registration:any;compact?:boolean}){
 const groups=registrationClassViewGroups(registration);
 if(!groups.length)return <span className="registration-classes-empty">Классы не указаны</span>;
 return <div className={'participant-registration-number-groups'+(compact?' is-compact':'')}>
  {groups.map(group=><section className="participant-registration-number-group" key={group.number}>
   <div className="participant-registration-number-title">НОМЕР {String(group.number||registration.participantNumber||0).padStart(3,'0')}</div>
   {group.directions.map(direction=><div className="participant-registration-direction-group" key={direction.name}>
    <span>{direction.name}</span><strong>{direction.items.map((item:any)=>item.class?.name||item.name).join(', ')}</strong>
   </div>)}
  </section>)}
 </div>;
}

