    <div className="participant-section-head"><div><span className="eyebrow">ИСТОРИЯ USD · КАРТОЧКА ЗАЯВКИ</span><h1>{registration.stage?.name||'Регистрация на этап'}</h1><p className="muted">{date(registration.stage?.date)} · {[registration.stage?.city,registration.stage?.venue].filter(Boolean).join(' · ')||'Место проведения уточняется'}</p></div><span className={'badge '+(registration.status==='CANCELLED'?'bad':inspection?.status==='PASSED'?'good':'')}>{registration.status==='CANCELLED'?'Отменена':inspection?.status==='PASSED'?'Инспекция пройдена':inspection?.status==='FAILED'?'Инспекция не пройдена':'Ожидает инспекции'}</span></div>
